"use client";

import { AnimatePresence, motion } from "framer-motion";
import styles from "./index.module.css";
import { useReferStore } from "@/app/store/useRefer";
import ReferModal from "@/app/components/layout/laptop/user/refer/modal";
import { useAccount } from "@/app/hooks/useAccount";
import { usePathname } from "next/navigation";

const Refer = (props: any) => {
  const { isMobile } = props;

  const pathname = usePathname();
  const store = useReferStore();
  const { address } = useAccount();

  const isMining = /^\/reward/.test(pathname);

  const handleEntryOpen = (e: any) => {
    e.stopPropagation();
    e.preventDefault();
    store.setEntryVisible(true);
  };

  const handleEntryClose = () => {
    store.setEntryVisible(false);
  };

  const handleOpen = () => {
    if (!address) {
      //@ts-ignore
      window.connect();
      return;
    }
    store.setVisible(true);
  };

  return (
    <div className={isMobile ? styles.ContainerMobile : styles.Container}>
      {isMobile ? (
        isMining && (
          <div className={isMobile ? styles.EntryMobile : styles.Entry}>
            <EntryAnimation
              onClick={handleEntryOpen}
              entryVisible={store.entryVisible}
              isMobile={isMobile}
            />
          </div>
        )
      ) : (
        <div className={isMobile ? styles.EntryMobile : styles.Entry}>
          <EntryAnimation
            onClick={handleEntryOpen}
            entryVisible={store.entryVisible}
            isMobile={isMobile}
          />
        </div>
      )}
      <motion.div
        className={isMobile ? styles.CardMobile : styles.Card}
        variants={{
          visible: {
            opacity: 1,
            scale: 1,
            x: isMobile ? 0 : 20,
            transition: {
              type: "spring",
              stiffness: 200,
              damping: 20
            }
          },
          invisible: {
            opacity: 0,
            scale: 0,
            x: "-100%"
          }
        }}
        initial="invisible"
        animate={
          (isMobile ? store.entryVisible && isMining : store.entryVisible)
            ? "visible"
            : "invisible"
        }
      >
        <ReferContent
          handleOpen={handleOpen}
          handleEntryClose={handleEntryClose}
        />
      </motion.div>
      <ReferModal {...props} />
    </div>
  );
};

export default Refer;

const ReferContent = (props: any) => {
  const { handleOpen, handleEntryClose, isMobile } = props;

  return (
    <>
      <div className={isMobile ? styles.CardInnerMobile : styles.CardInner}>
        <div className={styles.Title}>Invite frenz and Earn up to</div>
        <div className={styles.Content}>
          <div className={styles.Rebates}>
            <img
              src="/img/home/refer-reward-amount.png"
              alt=""
              className={styles.RebatesValue}
            />
            <div className={styles.RebatesUnit}></div>
          </div>
          <button
            type="button"
            className={styles.ReferBtn}
            onClick={handleOpen}
          >
            Invite
          </button>
        </div>
      </div>
      <button
        type="button"
        className={styles.CloseBtn}
        onClick={handleEntryClose}
      />
    </>
  );
};

